function updateQuality(){const ratio=contrast(els.fg.value,els.bg.value),rev=luminance(els.fg.value)>luminance(els.bg.value),density=state.qrModel?state.qrModel.getModuleCount():0;let cls='good',title=state.lang==='tr'?'Okunabilirlik iyi':'Readability looks good',msg=state.lang==='tr'?'Kontrast ve sessiz alan güvenli aralıkta.':'Contrast and quiet zone are in a safe range.';if(ratio<4.5){cls='bad';title=state.lang==='tr'?'Kontrast düşük':'Low contrast';msg=state.lang==='tr'?'QR ile arka plan arasındaki kontrastı artır.':'Increase contrast between QR and background.';}else if(rev||state.logoImage||els.gradient.checked||els.module.value!=='square'){cls='warn';title=state.lang==='tr'?'Gerçek cihazla test et':'Test with a real device';msg=state.lang==='tr'?'Logo, gradient veya stil kullanımı taramayı zorlaştırabilir.':'Logo, gradient or custom styling can make scanning harder.';}els.quality.className=`quality-box ${cls}`;els.qualityIcon.textContent=cls==='good'?'✓':cls==='warn'?'!':'×';els.qualityTitle.textContent=title;els.qualityText.textContent=`${msg} ${state.lang==='tr'?'Kontrast':'Contrast'} ${ratio.toFixed(1)}:1${density?` • ${density}×${density}`:''}`;}
function setVerify(cls,msg){els.verifyBadge.className=`verify-badge ${cls}`;els.verifyBadge.textContent=msg;}

async function validateCurrent(){if(!state.qrModel)return;const canvas=renderToCanvas(state.qrModel,1000,getOptions());if(state.detector){try{const results=await state.detector.detect(canvas);const match=results.some(r=>r.rawValue===state.payload);if(match){setVerify('good',state.lang==='tr'?'✓ Otomatik okuma doğrulandı':'✓ Automatic decode verified');return;}setVerify('bad',state.lang==='tr'?'Okunamadı — tasarımı sadeleştir':'Could not decode — simplify design');return;}catch{}}
  const ratio=contrast(els.fg.value,els.bg.value),safe=ratio>=4.5&&+els.quiet.value>=4;setVerify(safe?'warn':'bad',safe?(state.lang==='tr'?'Tarayıcı otomatik okuyamıyor; yapısal kontroller geçti':'Automatic decode unavailable; structural checks passed'):(state.lang==='tr'?'Yapısal risk bulundu':'Structural risk found'));}

function syncColor(color,hex){hex.value=color.value.toUpperCase();$$('.preset').forEach(p=>p.classList.remove('active'));updateQuality();queueGenerate();}
function syncHex(hex,color){const v=hex.value.trim();if(/^#[0-9a-f]{6}$/i.test(v)){color.value=v;syncColor(color,hex);}}
const PRESETS={classic:['#0b0b0d','#ffffff','#5b5ce2'],midnight:['#ffffff','#111114','#ff7a45'],ocean:['#083d77','#f3f8ff','#2aa6b8'],forest:['#174b35','#f3f8f3','#79a85b'],paper:['#000000','#ffffff','#444444'],berry:['#6d214f','#fff3fa','#d8629d']};
function applyPreset(name){const p=PRESETS[name];if(!p)return;els.fg.value=p[0];els.bg.value=p[1];els.accent.value=p[2];els.fgHex.value=p[0].toUpperCase();els.bgHex.value=p[1].toUpperCase();els.accentHex.value=p[2].toUpperCase();$$('.preset').forEach(b=>b.classList.toggle('active',b.dataset.preset===name));updateQuality();queueGenerate();}

async function loadLogoFile(file){if(!file)return;if(file.size>5*1024*1024)return toast(state.lang==='tr'?'Logo 5 MB veya daha küçük olmalı.':'Logo must be 5 MB or smaller.');try{const data=await fileToDataUrl(file);state.logoSource=await imageFromUrl(data);await processLogo();els.removeLogo.hidden=false;els.ecc.value='H';toast(state.lang==='tr'?'Logo eklendi; H hata düzeltme etkin.':'Logo added; H error correction enabled.');}catch{toast(state.lang==='tr'?'Logo okunamadı.':'Could not read logo.');}}
function fileToDataUrl(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});}
function imageFromUrl(url){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=url;});}
async function processLogo(){if(!state.logoSource){state.logoImage=null;state.logoDataUrl='';queueGenerate();return;}const src=state.logoSource,c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d'),pad=(+els.logoPadding.value||0)/100*512,bg=els.bg.value;ctx.fillStyle=bg;ctx.fillRect(0,0,512,512);if(els.logoShape.value==='circle'){ctx.save();ctx.beginPath();ctx.arc(256,256,256-pad,0,Math.PI*2);ctx.clip();}
  const avail=512-pad*2,shape=els.logoShape.value;let sx=0,sy=0,sw=src.width,sh=src.height,dx=pad,dy=pad,dw=avail,dh=avail;if(shape==='contain'){const scale=Math.min(avail/src.width,avail/src.height);dw=src.width*scale;dh=src.height*scale;dx=(512-dw)/2;dy=(512-dh)/2;}else{const side=Math.min(src.width,src.height);sx=(src.width-side)/2;sy=(src.height-side)/2;sw=sh=side;}ctx.drawImage(src,sx,sy,sw,sh,dx,dy,dw,dh);if(shape==='circle')ctx.restore();state.logoDataUrl=c.toDataURL('image/png');state.logoImage=await imageFromUrl(state.logoDataUrl);els.logoPaddingValue.textContent=`${els.logoPadding.value}%`;updateQuality();queueGenerate();}
function removeLogo(){state.logoSource=null;state.logoImage=null;state.logoDataUrl='';els.logoInput.value='';els.removeLogo.hidden=true;queueGenerate();updateQuality();}
async function fetchFavicon(){if(state.type!=='url'||!state.forms.url.url)return toast(state.lang==='tr'?'Önce bir web adresi gir.':'Enter a website first.');let u;try{u=new URL(safeUrl(state.forms.url.url));}catch{return toast(state.lang==='tr'?'URL geçersiz.':'Invalid URL.');}toast(state.lang==='tr'?'Hedef sitenin favicon dosyası deneniyor…':'Trying the target site favicon…');try{const r=await fetch(new URL('/favicon.ico',u).href,{mode:'cors',credentials:'omit'});if(!r.ok)throw 0;const b=await r.blob();if(!b.type.startsWith('image/'))throw 0;await loadLogoFile(new File([b],'favicon.ico',{type:b.type}));}catch{toast(state.lang==='tr'?'Site CORS nedeniyle favicon paylaşmadı. Logoyu dosya olarak yükleyebilirsin.':'The site did not expose its favicon via CORS. Upload the logo file instead.');}}

async function exportPNG(){if(!state.qrModel)return;const c=renderToCanvas(state.qrModel,+els.pngSize.value||2048,getOptions());c.toBlob(b=>b&&downloadBlob(b,`${filenameBase()}.png`),'image/png');}
function exportSVG(){if(!state.qrModel)return;const s=buildSvg(state.qrModel,getOptions());downloadBlob(new Blob([s],{type:'image/svg+xml;charset=utf-8'}),`${filenameBase()}.svg`);}
async function shareQR(){if(!state.qrModel)return;const c=renderToCanvas(state.qrModel,1200,getOptions());const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(window.OzinaryNative){downloadBlob(blob,`${filenameBase()}.png`);return;}const file=new File([blob],`${filenameBase()}.png`,{type:'image/png'});try{if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]})))await navigator.share({files:[file],title:'Ozinary QR'});else downloadBlob(blob,file.name);}catch(e){if(e.name!=='AbortError')downloadBlob(blob,file.name);}}
async function socialCard(){if(!state.qrModel)return;const c=document.createElement('canvas');c.width=1080;c.height=1920;const ctx=c.getContext('2d');ctx.fillStyle=els.bg.value;ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle=els.fg.value;ctx.textAlign='center';ctx.font='800 56px Inter,Arial';ctx.fillText('OZINARY QR',540,190);ctx.font='800 64px Inter,Arial';const title=els.label.value.trim()||(state.lang==='tr'?'Tara ve keşfet':'Scan to open');ctx.fillText(title,540,340);const qr=renderToCanvas(state.qrModel,760,getOptions({frame:'none',label:''}));ctx.drawImage(qr,(1080-760)/2,520,760,760);ctx.font='500 28px Inter,Arial';ctx.fillText('ozinary.com',540,1500);ctx.font='500 24px Inter,Arial';ctx.fillText(state.lang==='tr'?'Ücretsiz • Sınırsız • Gizlilik odaklı':'Free • Unlimited • Privacy-first',540,1550);c.toBlob(b=>b&&downloadBlob(b,`${filenameBase()}-story.png`),'image/png');}
function printCurrent(custom=false){if(!state.qrModel)return;const sheet=$('#printSheet');sheet.innerHTML='';let count;if(custom){const cols=Math.min(8,Math.max(1,+$('#customCols').value||3)),rows=Math.min(12,Math.max(1,+$('#customRows').value||5));count=cols*rows;sheet.className='print-sheet print-custom';sheet.style.setProperty('--print-cols',cols);sheet.style.setProperty('--print-rows',rows);}else{count=+$('#printCount').value||4;sheet.className=`print-sheet print-${count}`;sheet.style.removeProperty('--print-cols');sheet.style.removeProperty('--print-rows');}for(let i=0;i<count;i++){const item=document.createElement('div');item.className='print-item';item.appendChild(renderToCanvas(state.qrModel,count<=4?900:count<=16?600:420,getOptions()));sheet.appendChild(item);}sheet.setAttribute('aria-hidden','false');document.body.classList.add('printing');setTimeout(()=>window.print(),60);}

function base64Bytes(dataUrl){const b=atob(dataUrl.split(',')[1]);const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u;}
function concatBytes(parts){const len=parts.reduce((n,p)=>n+p.length,0),out=new Uint8Array(len);let o=0;for(const p of parts){out.set(p,o);o+=p.length;}return out;}
function ascii(s){return enc.encode(s);}
function makePdfWithJpeg(jpeg,wpx,hpx,placements,pageWmm=210,pageHmm=297){const pt=72/25.4,W=pageWmm*pt,H=pageHmm*pt;const content=placements.map(p=>`q ${p.w*pt} 0 0 ${p.h*pt} ${p.x*pt} ${(pageHmm-p.y-p.h)*pt} cm /Im1 Do Q${p.stroke?`\n0.7 w ${p.x*pt} ${(pageHmm-p.y-p.h)*pt} ${p.w*pt} ${p.h*pt} re S`:''}`).join('\n');const objs=[];objs[1]=ascii('<< /Type /Catalog /Pages 2 0 R >>');objs[2]=ascii('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');objs[3]=ascii(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /XObject << /Im1 4 0 R >> >> /Contents 5 0 R >>`);objs[4]=concatBytes([ascii(`<< /Type /XObject /Subtype /Image /Width ${wpx} /Height ${hpx} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`),jpeg,ascii('\nendstream')]);objs[5]=ascii(`<< /Length ${ascii(content).length} >>\nstream\n${content}\nendstream`);const header=ascii('%PDF-1.4\n%1234\n');const parts=[header];const offs=[0];let pos=header.length;for(let i=1;i<=5;i++){offs[i]=pos;const ob=concatBytes([ascii(`${i} 0 obj\n`),objs[i],ascii('\nendobj\n')]);parts.push(ob);pos+=ob.length;}const xrefPos=pos;let x=`xref\n0 6\n0000000000 65535 f \n`;for(let i=1;i<=5;i++)x+=String(offs[i]).padStart(10,'0')+' 00000 n \n';x+=`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF`;parts.push(ascii(x));return new Blob([concatBytes(parts)],{type:'application/pdf'});}
async function exportPDF(sticker=false){if(!state.qrModel)return;const c=renderToCanvas(state.qrModel,1400,getOptions()),data=c.toDataURL('image/jpeg',.96),jpg=base64Bytes(data);let placements=[];if(!sticker){const ratio=c.height/c.width,w=160,h=w*ratio;placements=[{x:(210-w)/2,y:(297-h)/2,w,h}];downloadBlob(makePdfWithJpeg(jpg,c.width,c.height,placements),`${filenameBase()}.pdf`);return;}const cell=+$('#stickerSize').value||70,gap=4,margin=10,cols=Math.max(1,Math.floor((210-2*margin+gap)/(cell+gap))),rows=Math.max(1,Math.floor((297-2*margin+gap)/(cell+gap))),totalW=cols*cell+(cols-1)*gap,totalH=rows*cell+(rows-1)*gap,sx=(210-totalW)/2,sy=(297-totalH)/2,ratio=c.height/c.width;for(let r=0;r<rows;r++)for(let col=0;col<cols;col++){let w=cell,h=cell;if(ratio>1)w=cell/ratio;else h=cell*ratio;placements.push({x:sx+col*(cell+gap)+(cell-w)/2,y:sy+r*(cell+gap)+(cell-h)/2,w,h,stroke:true});}downloadBlob(makePdfWithJpeg(jpg,c.width,c.height,placements),`${filenameBase()}-stickers-${cell}mm.pdf`);}

function cleanUrl(raw){try{const u=new URL(safeUrl(raw));[...u.searchParams.keys()].forEach(k=>{const l=k.toLowerCase();if(l.startsWith('utm_')||TRACKING_KEYS.includes(l))u.searchParams.delete(k);});return u.href;}catch{return raw;}}
function calculateSize(){const d=Math.max(10,+$('#scanDistance').value||100),modules=state.qrModel?state.qrModel.getModuleCount()+2*(+els.quiet.value||4):37,byDistance=d,byModule=modules*.4,reco=Math.max(byDistance,byModule);$('#sizeCalcResult').textContent=`${state.lang==='tr'?'Önerilen minimum':'Suggested minimum'}: ${Math.ceil(reco)} mm • ${state.lang==='tr'?'yaklaşık':'approx.'} ${(d/(reco/10)).toFixed(1)}:1`;} 

function parseCsv(text){const lines=String(text).replace(/^\uFEFF/,'').split(/\r?\n/).filter(l=>l.trim());if(!lines.length)return[];const first=lines[0],delim=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':(first.includes('\t')?'\t':',');const parseLine=line=>{const out=[];let cur='',q=false;for(let i=0;i<=line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if((ch===delim||i===line.length)&&!q){out.push(cur.trim());cur='';}else if(i<line.length)cur+=ch;}return out;};let rows=lines.map(parseLine);const h=rows[0].map(s=>s.toLowerCase());if(h.includes('content')||h.includes('url')||h.includes('payload'))rows=rows.slice(1);return rows.map((r,i)=>({name:r[0]||`qr-${i+1}`,content:r[1]||r[0]||''})).filter(x=>x.content).slice(0,500);}
