function makeZip(files){const locals=[],centrals=[];let offset=0;const dt=dosTimeDate();for(const f of files){const name=enc.encode(f.name),data=f.data instanceof Uint8Array?f.data:enc.encode(f.data),crc=crc32(data);const local=concatBytes([le32(0x04034b50),le16(20),le16(0x0800),le16(0),le16(dt.time),le16(dt.date),le32(crc),le32(data.length),le32(data.length),le16(name.length),le16(0),name,data]);locals.push(local);const cent=concatBytes([le32(0x02014b50),le16(20),le16(20),le16(0x0800),le16(0),le16(dt.time),le16(dt.date),le32(crc),le32(data.length),le32(data.length),le16(name.length),le16(0),le16(0),le16(0),le16(0),le32(0),le32(offset),name]);centrals.push(cent);offset+=local.length;}const central=concatBytes(centrals),localAll=concatBytes(locals),end=concatBytes([le32(0x06054b50),le16(0),le16(0),le16(files.length),le16(files.length),le32(central.length),le32(localAll.length),le16(0)]);return new Blob([localAll,central,end],{type:'application/zip'});}
async function blobBytes(blob){return new Uint8Array(await blob.arrayBuffer());}
async function generateBatch(){const rows=parseCsv($('#batchText').value);if(!rows.length)return toast(state.lang==='tr'?'Geçerli kayıt bulunamadı.':'No valid rows found.');const format=$('#batchFormat').value,sz=+$('#batchPngSize').value||1024,useStyle=$('#batchUseStyle').checked,files=[];$('#batchGenerateBtn').disabled=true;for(let i=0;i<rows.length;i++){const r=rows[i];try{const model=createQrModel(r.content,useStyle?els.ecc.value:'H');const opt=useStyle?getOptions({label:''}):{fg:'#000000',bg:'#ffffff',accent:'#000000',gradient:false,module:'square',eye:'square',ecc:'H',quiet:4,frame:'none',label:'',logo:null,logoDataUrl:'',logoPadding:12};if(format==='png'||format==='both'){const c=renderToCanvas(model,sz,opt),b=await new Promise(res=>c.toBlob(res,'image/png'));files.push({name:`${String(i+1).padStart(3,'0')}-${slugify(r.name)}.png`,data:await blobBytes(b)});}if(format==='svg'||format==='both')files.push({name:`${String(i+1).padStart(3,'0')}-${slugify(r.name)}.svg`,data:buildSvg(model,opt)});}catch{files.push({name:`ERROR-${i+1}-${slugify(r.name)}.txt`,data:'QR could not be generated for this row.'});}const pct=Math.round((i+1)/rows.length*100);$('#batchProgress span').style.width=pct+'%';$('#batchStatus').textContent=`${i+1}/${rows.length}`;await new Promise(r=>setTimeout(r,0));}files.push({name:'README.txt',data:'Generated locally by Ozinary QR. No CSV content was uploaded to the application server.'});downloadBlob(makeZip(files),`ozinary-qr-batch-${rows.length}.zip`);$('#batchGenerateBtn').disabled=false;state.batchResultCount=rows.length;$('#batchStatus').textContent=state.lang==='tr'?`${rows.length} QR hazır`:`${rows.length} QRs ready`;}

async function setupDetector(){if(window.OzinaryNative&&window.jsQR){state.detector={detect:async(source)=>{const c=document.createElement('canvas');c.width=source.width;c.height=source.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0);const pixels=ctx.getImageData(0,0,c.width,c.height);const result=window.jsQR(pixels.data,c.width,c.height);return result?[{rawValue:result.data}]:[];}};$('#scannerSupport').textContent=state.lang==='tr'?'Cihaz içi QR tarama':'On-device QR scanning';$('#scannerSupport').className='support-chip good';return;}if(!('BarcodeDetector'in window)){state.detector=null;$('#scannerSupport').textContent=state.lang==='tr'?'Bu tarayıcı scanner API desteklemiyor':'Scanner API not supported';$('#scannerSupport').className='support-chip warn';els.verifySub.textContent=state.lang==='tr'?'Yapısal kontrol yapılır':'Structural checks only';return;}try{state.detector=new BarcodeDetector({formats:['qr_code']});$('#scannerSupport').textContent=state.lang==='tr'?'QR tarama destekleniyor':'QR scanning supported';$('#scannerSupport').className='support-chip good';}catch{state.detector=null;}}
function handleScanResult(raw){$('#scanResult').value=raw||'';const open=$('#openScanLink');if(/^https?:\/\//i.test(raw)){open.href=raw;open.hidden=false;}else open.hidden=true;toast(state.lang==='tr'?'QR okundu.':'QR decoded.');}
async function scanImageFile(file){if(!state.detector)return toast(state.lang==='tr'?'Bu tarayıcı görselden QR okumayı desteklemiyor.':'This browser does not support image QR scanning.');try{const bmp=await createImageBitmap(file),r=await state.detector.detect(bmp);bmp.close?.();if(r.length)handleScanResult(r[0].rawValue);else toast(state.lang==='tr'?'Görselde QR bulunamadı.':'No QR found in image.');}catch{toast(state.lang==='tr'?'Görsel okunamadı.':'Could not scan image.');}}
async function startCamera(){if(!state.detector)return toast(state.lang==='tr'?'Tarayıcı QR scanner API desteklemiyor.':'Browser QR scanner API is unavailable.');try{state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const v=$('#scannerVideo');v.srcObject=state.stream;await v.play();$('#startScanBtn').disabled=true;$('#stopScanBtn').disabled=false;const loop=async()=>{if(!state.stream)return;try{if(v.readyState>=2){const r=await state.detector.detect(v);if(r.length){handleScanResult(r[0].rawValue);stopCamera();return;}}}catch{}state.scanTimer=setTimeout(loop,220);};loop();}catch{toast(state.lang==='tr'?'Kamera açılamadı. HTTPS ve kamera iznini kontrol et.':'Could not open camera. Check HTTPS and camera permission.');}}
function stopCamera(){clearTimeout(state.scanTimer);state.scanTimer=null;if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null;}const v=$('#scannerVideo');v.srcObject=null;$('#startScanBtn').disabled=false;$('#stopScanBtn').disabled=true;}

