function saveProject(auto=false){let name=auto?`Auto ${new Date().toLocaleString()}`:prompt(state.lang==='tr'?'Proje adı:':'Project name:',els.label.value||filenameBase());if(!name)return;const p=collectProject(name),arr=readProjects();if(auto){const sig=state.type+'|'+state.payload+'|'+JSON.stringify(p.design);if(arr[0]?._sig===sig)return;p._sig=sig;}arr.unshift(p);if(!writeProjects(arr))return;if(!auto)toast(state.lang==='tr'?'Bu cihazda kaydedildi.':'Saved on this device.');}
function scheduleAutoHistory(){if(!$('#autoHistory').checked||!state.payload)return;clearTimeout(state.autoTimer);state.autoTimer=setTimeout(()=>saveProject(true),2500);}
function renderProjects(){const box=$('#projectList'),arr=readProjects();if(!arr.length){box.innerHTML=`<span class="muted">${state.lang==='tr'?'Henüz kayıt yok.':'No saved projects yet.'}</span>`;return;}box.innerHTML=arr.map((p,i)=>`<div class="project-item"><div><strong>${escapeHtml(p.name||'QR')}</strong><small>${escapeHtml(new Date(p.savedAt).toLocaleString(state.lang==='tr'?'tr-TR':'en-US'))}</small></div><div class="row-actions"><button class="ghost-btn" data-load-project="${i}" type="button">${state.lang==='tr'?'Aç':'Open'}</button><button class="ghost-btn danger" data-delete-project="${i}" type="button">×</button></div></div>`).join('');}
async function applyProject(p){if(!p||!p.forms)return;state.type=p.type||'url';state.forms=Object.assign(state.forms,p.forms);$$('.tab').forEach(t=>{const on=t.dataset.type===state.type;t.classList.toggle('active',on);t.setAttribute('aria-selected',on?'true':'false');});const d=p.design||{};[['fg',els.fg],['bg',els.bg],['accent',els.accent]].forEach(([k,e])=>{if(d[k])e.value=d[k];});els.fgHex.value=els.fg.value.toUpperCase();els.bgHex.value=els.bg.value.toUpperCase();els.accentHex.value=els.accent.value.toUpperCase();['module','eye','ecc','quiet','pngSize','frame','logoShape','logoPadding'].forEach(k=>{const e={module:els.module,eye:els.eye,ecc:els.ecc,quiet:els.quiet,pngSize:els.pngSize,frame:els.frame,logoShape:els.logoShape,logoPadding:els.logoPadding}[k];if(d[k]!=null)e.value=d[k];});els.gradient.checked=!!d.gradient;els.accentWrap.hidden=!els.gradient.checked;els.label.value=d.label||'';if(d.logoDataUrl){state.logoSource=await imageFromUrl(d.logoDataUrl);await processLogo();els.removeLogo.hidden=false;}else removeLogo();renderFields();queueGenerate();}
function exportProject(){downloadBlob(new Blob([JSON.stringify(collectProject(),null,2)],{type:'application/json'}),`${filenameBase()}.json`);}
function validateProject(p){if(!p||typeof p!=='object'||!Object.hasOwn(state.forms,p.type)||!p.forms||typeof p.forms!=='object')throw new Error('Invalid project');const forms=structuredClone(state.forms);for(const [type,fields]of Object.entries(forms)){const input=p.forms[type];if(!input)continue;for(const key of Object.keys(fields)){if(!Object.hasOwn(input,key))continue;const value=input[key];if(key==='hidden'){if(typeof value!=='boolean')throw new Error('Invalid field');}else if(typeof value!=='string'||value.length>10000)throw new Error('Invalid field');fields[key]=value;}}const d=p.design||{},design={};for(const key of ['fg','bg','accent'])if(d[key]!=null){if(!/^#[0-9a-f]{6}$/i.test(d[key]))throw new Error('Invalid color');design[key]=d[key];}const choices={module:['square','rounded','dots','diamond'],eye:['square','rounded','circle'],ecc:['L','M','Q','H'],quiet:['4','6','8'],pngSize:['1024','2048','4096'],frame:['none','border','card','cta'],logoShape:['square','circle','contain']};for(const [key,values]of Object.entries(choices))if(d[key]!=null){if(!values.includes(String(d[key])))throw new Error('Invalid design');design[key]=String(d[key]);}if(d.gradient!=null){if(typeof d.gradient!=='boolean')throw new Error('Invalid gradient');design.gradient=d.gradient;}if(d.label!=null){if(typeof d.label!=='string'||d.label.length>1000)throw new Error('Invalid label');design.label=d.label;}if(d.logoPadding!=null){const pad=Number(d.logoPadding);if(!Number.isFinite(pad)||pad<0||pad>40)throw new Error('Invalid padding');design.logoPadding=String(pad);}if(d.logoDataUrl){if(typeof d.logoDataUrl!=='string'||d.logoDataUrl.length>8*1024*1024||!/^data:image\/(?:png|jpeg|webp|svg\+xml);base64,/i.test(d.logoDataUrl))throw new Error('Invalid logo');design.logoDataUrl=d.logoDataUrl;}return{type:p.type,forms,design};}
