// Capture only source UI strings, before dynamic fields, projects and results exist.
// Entered QR data, saved project names and output values are never translated.
const languageNodes=[],languageAttributes=[];
function captureLanguageEntries(){
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
  while(node=walker.nextNode()){
    if(node.parentElement?.closest('script,style,textarea,#fields,#projectList,#payloadText,#cleanUrlOutput,#developerOutput,#toast,#qrEngine')||!node.nodeValue.trim())continue;
    if(Object.hasOwn(TR_EN,node.nodeValue.trim()))languageNodes.push({node,original:node.nodeValue});
  }
  $$('[placeholder],[title],[aria-label],[alt]').forEach(element=>{
    for(const attribute of ['placeholder','title','aria-label','alt']){
      const original=element.getAttribute(attribute);
      if(original&&Object.hasOwn(TR_EN,original))languageAttributes.push({element,attribute,original});
    }
  });
}
function applyLanguage(){
  document.documentElement.lang=state.lang;$('#langBtn').textContent=state.lang==='tr'?'EN':'TR';
  languageNodes.forEach(({node,original})=>{const text=original.trim();node.nodeValue=state.lang==='en'?original.replace(text,TR_EN[text]):original;});
  languageAttributes.forEach(({element,attribute,original})=>element.setAttribute(attribute,state.lang==='en'?TR_EN[original]:original));
  if(window.OzinaryNative)window.OzinaryNative.language=state.lang;
}
